        if parent=='obj':
            stdin = f'{{"a": [{elem}]}}'
        else:
            stdin = f'[[{elem}]]'
        out = run(stdin)
        # extract inner representation: check if inline (contains "[ " or "{\n")
        print(f"parent={parent} elem={elem} => {out!r}")

print("--- multi ---")
for parent in ['obj', 'arr']:
    for elems in ['1,2', '"a","b"', 'true,false', 'null,null', '1,"a"', '[],[]', '[1],[2]']:
        if parent=='obj':
            stdin = f'{{"a": [{elems}]}}'
        else:
