import sys, re, math

class Undefined:
    pass
UNDEFINED = Undefined()

class BigInt(int):
    pass

class JSFunction:
    def __init__(self, params, body, is_arrow, code):
        self.params = params
        self.body = body
        self.is_arrow = is_arrow
        self.code = code

class JSONParseError(Exception):
    def __init__(self, msg, line_text, line_num, col):
        super().__init__(msg)
        self.msg = msg
        self.line_text = line_text
        self.line_num = line_num
        self.col = col
    def format(self):
        dots = '.' * self.col
        return f"{self.msg} on line {self.line_num}.\n\n  {self.line_text}\n  {dots}^\n\n"

def escape_for_msg(c):
    if c == '\x00':
        return '\\x00'
    elif c == '\n':
        return '\\n'
    elif c == '\r':
        return '\\r'
    elif c == '\t':
        return '\\t'
    elif c == "'":
        return "\\'"
    elif c == "\\":
        return "\\\\"
    else:
        return c

# JSON parser that returns list of values with preserve info
class JSONParser:
    def __init__(self, text, strict=False):
        self.text = text
        self.n = len(text)
        self.pos = 0
        self.strict = strict

    def current_line_info(self, p):
        if p > self.n:
            p = self.n
        ln = self.text.count('\n', 0, p) + 1
        ls = self.text.rfind('\n', 0, p)
        if ls == -1:
            ls = 0
        else:
            ls += 1
        le = self.text.find('\n', p)
        if le == -1:
            le = self.n
        line_text = self.text[ls:le]
        # strip \r?
        if line_text.endswith('\r'):
            line_text = line_text[:-1]
        col = p - ls
        return line_text, ln, col

    def error(self, msg_template, p, char=None, context=None):
        # msg_template like "Unexpected character" or "Invalid character" or "Expected object key..."
        # char is the offending char (for quoting), context is "in object"/"in array"/"in number"/"in keyword" or None
        line_text, ln, col = self.current_line_info(p)
        if p >= self.n:
            # EOF
            ch_esc = '\\x00'
            if msg_template.startswith("Unexpected character"):
                if context:
                    msg = f"Unexpected character '{ch_esc}' {context}"
                else:
                    msg = f"Unexpected character '{ch_esc}'"
            elif msg_template.startswith("Invalid character"):
                msg = f"Invalid character '{ch_esc}' {context}" if context else f"Invalid character '{ch_esc}'"
            elif msg_template.startswith("Expected object key"):
                # shouldn't happen at EOF? but handle
                msg = msg_template
            elif msg_template.startswith("Trailing comma") or msg_template.startswith("Comments are"):
                msg = msg_template
            elif "end of input" in msg_template:
                # e.g., "Unexpected end of input in string"
                # line_text for string unterminated: original shows line 2 empty for '{"a": "unterminated}\n' ?
                # That input is '{"a": "unterminated}\n' (one line + newline). Error line 2, empty. So p at EOF (after \n?), line 2.
                msg = msg_template
            else:
                msg = msg_template
            # For EOF whitespace-only case, col adjustment: if line_text non-empty (whitespace), col should be len-1? Let's handle in caller.
            # Actually for whitespace-only EOF, our col from current_line_info is len(line_text) (since p at end). But expected is len-1.
            # Check: input '   ' (3 spaces, no \n), p=3, line_text="   ", col=3, but expected 2. So adjust: if line_text is all whitespace and p==n, col = max(0, len(line_text)-1) ??? 
            # For '\n' (p=1, line_text="" (after \n), col=0, expected 0. Good (len 0, col 0).
            # For '   \n' (3 spaces + \n, len 4, p=4, line_text="" (after \n), col 0, expected 0. Good.
            # So only when line_text non-empty (no trailing \n), adjust.
            if line_text != "" and p == self.n and self.text and not self.text.endswith('\n'):
                # check if line_text is whitespace-only? For '   ', yes. For other EOF like '{"a": tru' (no \n, truncated)? That would be different.
                # For '   ', we want col 2. For '{"a": tru' (?) Not in tests. We'll just if p==n and col==len(line_text): col = max(0, col-1) ??? But for '{"a": "unterminated}' without \n? That would be string unterminated at EOF, not whitespace. Its error is "Unexpected end of input in string", not whitespace. So not affected.
                # For whitespace EOF, adjust.
                # Detect if remaining is whitespace? Actually p==n, line_text is last line. If last line is whitespace and no value, we adjust.
                # Simpler: if col == len(line_text) and len(line_text)>0:
                #   col -= 1
                if col == len(line_text) and len(line_text) > 0:
                    col -= 1
            raise JSONParseError(msg, line_text, ln, col)
        else:
            ch = self.text[p]
            ch_esc = escape_for_msg(ch)
            # Special handling for single quote in "Expected object key..."? That message has got 'X' with escaping.
            if msg_template.startswith("Expected object key"):
                # msg_template is full "Expected object key to be a string, got 'X'" where X already escaped? We'll construct.
                # char is the got char (e.g., 'a' or "'")
                msg = f"Expected object key to be a string, got '{ch_esc}'"
