    def peek(self):
        if self.pos >= self.n:
            return None
        return self.text[self.pos]

    def skip_ws_comments(self):
        while self.pos < self.n:
            c = self.text[self.pos]
            if c in ' \t\r\n':
                self.pos += 1
            elif not self.strict and c == '/' and self.pos+1 < self.n and self.text[self.pos+1] == '/':
                # // comment
                # In strict, error
                # In non-strict, skip until \n (not including \n? Original preserves? For error reporting, comments are skipped.)
                self.pos += 2
                while self.pos < self.n and self.text[self.pos] != '\n':
                    self.pos += 1
                # leave \n for whitespace handling? Actually \n will be skipped next loop as whitespace.
            elif not self.strict and c == '/' and self.pos+1 < self.n and self.text[self.pos+1] == '*':
                self.pos += 2
                # skip until */
                found = False
                while self.pos < self.n:
                    if self.text[self.pos] == '*' and self.pos+1 < self.n and self.text[self.pos+1] == '/':
                        self.pos += 2
                        found = True
                        break
                    self.pos += 1
                if not found:
