                    pass
            elif self.strict and c == '/' and self.pos+1 < self.n and self.text[self.pos+1] in ('/', '*'):
                # Strict: comments not allowed
                # Error at c position
                line_text, ln, col = self.current_line_info(self.pos)
                raise JSONParseError("Comments are not allowed in strict mode", line_text, ln, col)
            else:
                break

    def parse_value(self):
        self.skip_ws_comments()
        if self.pos >= self.n:
            return None  # EOF, no value
        c = self.text[self.pos]
        if c == '{':
            return self.parse_object()
        elif c == '[':
            return self.parse_array()
        elif c == '"':
            return self.parse_string()
        elif c == '-' or c.isdigit():
            return self.parse_number_or_literal()
        elif c == 't' or c == 'f' or c == 'n' or c == 'N' or c == 'I' or c == 'u':
            # true, false, null, NaN, Infinity, Inf, undefined, etc.
            # Also 'n' could be null or NaN? 'N' for NaN, 'I' for Infinity/Inf, 'u' for undefined
            return self.parse_literal()
        else:
