        # To handle preserve, we need to return both js_value and preserve_value. For objects, preserve_value is dict with same keys but values are preserve versions (numbers as strings, strings as raw, etc.)
        # We'll return a tuple (js_val, preserve_val) where preserve_val for numbers/strings is original, for others recursive.
        # For simplicity, parse returns (js, preserve)
        # Let's implement parse_object returning (js_dict, preserve_dict, key_order)
        # Use OrderedDict? Python 3.7+ preserves order.
        js_obj = {}
        preserve_obj = {}
        order = []
        if self.peek() == '}':
            self.pos += 1
            return (js_obj, preserve_obj, order, 'object')
        while True:
